mapper.insert:
INSERT INTO investigation_run (
    run_id, investigation_id, attempt, status, run_version, started_at, finished_at
) VALUES (
    #{runId}, #{investigationId}, #{attempt}, #{status}, #{version}, #{startedAt}, #{finishedAt}
)

INSERT INTO investigation_step (
    step_id, investigation_id, run_id, step_sequence, step_type, outcome_code, recorded_at
) VALUES (
    #{value.stepId}, #{investigationId}, #{value.runId}, #{value.stepSequence},
    #{value.stepType}, #{value.outcomeCode}, #{value.recordedAt}
)

INSERT INTO investigation_observation (
    observation_id, investigation_id, evidence_ref, summary_code, observed_at
) VALUES (
    #{observationId}, #{investigationId}, #{evidenceRef}, #{summaryCode}, #{observedAt}
)

INSERT INTO investigation_hypothesis (
    hypothesis_id, investigation_id, statement_code, status, evidence_refs, updated_at
) VALUES (
    #{hypothesisId}, #{investigationId}, #{statementCode}, #{status}, #{evidenceRefs}, #{updatedAt}
)

INSERT INTO investigation_checkpoint (
    checkpoint_id, investigation_id, run_id, aggregate_version, next_step_sequence,
    external_call_state, created_at
) VALUES (
    #{checkpointId}, #{investigationId}, #{runId}, #{aggregateVersion}, #{nextStepSequence},
    #{externalCallState}, #{createdAt}
)

INSERT INTO investigation_command_receipt (
    command_id, investigation_id, canonical_sha256, outcome_code, recorded_at
) VALUES (
    #{commandId}, #{investigationId}, #{canonicalSha256}, #{outcomeCode}, #{recordedAt}
)

INSERT INTO investigation_external_call (
    call_id, investigation_id, idempotency_key, call_state, attempt, result_code, updated_at
) VALUES (
    #{callId}, #{investigationId}, #{idempotencyKey}, #{state}, #{attempt}, #{resultCode}, #{updatedAt}
)
